1	<!doctype html>
2	<html lang="zh-CN">
3	<meta charset="utf-8">
4	<meta name="viewport" content="width=device-width,initial-scale=1">
5	<title>ScoreArena · 桌面规则游戏与赛事管理</title>
6	<style>
7	  :root { color-scheme: light; }
8	  body { font-family: system-ui, sans-serif; max-width: 52rem; margin: 3rem auto; padding: 0 1rem; line-height: 1.7; color: #1f2933; }
9	  h1 { margin-bottom: .25rem; }
10	  .sub { color: #52606d; margin-top: 0; }
11	  h2 { margin-top: 2.5rem; border-bottom: 1px solid #e4e7eb; padding-bottom: .35rem; }
12	  a { color: #175b9c; }
13	  form { background: #f8f9fb; border: 1px solid #e4e7eb; border-radius: .5rem; padding: 1.25rem 1.5rem; }
14	  .field { display: grid; grid-template-columns: 9rem 1fr; gap: .75rem; align-items: center; margin-bottom: 1rem; }
15	  label { font-weight: 600; }
16	  input, select { font: inherit; padding: .4rem .55rem; border: 1px solid #cbd2d9; border-radius: .35rem; background: #fff; }
17	  input:focus, select:focus { outline: 2px solid #9ec5fe; outline-offset: 1px; border-color: #175b9c; }
18	  .hint { grid-column: 2; color: #616e7c; font-size: .9rem; margin: -.35rem 0 0; }
19	  .actions { grid-column: 2; margin-top: .25rem; }
20	  button { font: inherit; font-weight: 600; padding: .5rem 1.4rem; border: none; border-radius: .35rem; background: #175b9c; color: #fff; cursor: pointer; }
21	  button:disabled { background: #9aa5b1; cursor: wait; }
22	  .msg { margin: 1rem 0 0; padding: .6rem .9rem; border-radius: .35rem; display: none; }
23	  .msg.show { display: block; }
24	  .msg.error { background: #fde8e8; border: 1px solid #f5b5b5; color: #9b1c1c; }
25	  .msg.ok { background: #e6f6ec; border: 1px solid #a7e0bd; color: #146134; }
26	  table { width: 100%; border-collapse: collapse; font-size: .95rem; }
27	  th, td { text-align: left; padding: .55rem .6rem; border-bottom: 1px solid #e4e7eb; vertical-align: top; }
28	  th { color: #52606d; font-size: .85rem; white-space: nowrap; }
29	  td.id, code { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: .85rem; word-break: break-all; }
30	  .empty { color: #616e7c; }
31	  .list-error { color: #9b1c1c; }
32	  .badge { display: inline-block; padding: .05rem .55rem; border-radius: 999px; background: #fff3c4; color: #7c4a03; font-size: .85rem; }
33	  .meta { color: #7b8794; font-size: .85rem; }
34	</style>
35	<main>
36	  <h1>ScoreArena</h1>
37	  <p class="sub">桌面规则游戏与赛事管理</p>
38	
39	  <h2>创建公开房间</h2>
40	  <form id="room-form" novalidate>
41	    <div class="field">
42	      <label for="name">房间名称</label>
43	      <input id="name" name="name" type="text" maxlength="80" autocomplete="off"
44	             placeholder="1–40 个字符，首尾空白会被去掉" required>
45	      <p class="hint">名称会去掉首尾空白后保存，内部空格保留；长度按 Unicode 字符计。</p>
46	    </div>
47	    <div class="field">
48	      <label for="game">游戏规则</label>
49	      <select id="game" name="game" required>
50	        <option value="" selected>请选择游戏规则…</option>
51	        <option value="gomoku">五子棋（gomoku）</option>
52	        <option value="ludo">飞行棋（ludo）</option>
53	      </select>
54	    </div>
55	    <div class="field">
56	      <label for="capacity">人数上限</label>
57	      <select id="capacity" name="capacity" required disabled>
58	        <option value="" selected>请先选择游戏规则</option>
59	      </select>
60	      <p class="hint" id="capacity-hint">五子棋人数固定为 2 人；飞行棋允许 2 至 4 人。</p>
61	    </div>
62	    <div class="field">
63	      <label for="turnSeconds">每步时间限制</label>
64	      <input id="turnSeconds" name="turnSeconds" type="number" step="1" inputmode="numeric"
65	             placeholder="秒，0 表示不限时" required>
66	      <p class="hint">以秒为单位：填 <strong>0</strong> 表示不限时；其他值必须是 10 至 600 之间的整数。</p>
67	    </div>
68	    <div class="field">
69	      <div></div>
70	      <div class="actions">
71	        <button type="submit" id="submit">创建房间</button>
72	      </div>
73	    </div>
74	    <p class="msg" id="form-msg" role="alert"></p>
75	  </form>
76	
77	  <h2>房间列表</h2>
78	  <div id="list-area">
79	    <p class="empty" id="empty-tip">还没有房间记录。</p>
80	  </div>
81	
82	  <p class="meta"><a href="/api/rooms">查看房间列表接口</a> · <a href="/health">服务状态</a></p>
83	</main>
84	
85	<script>
86	(function () {
87	  var form = document.getElementById('room-form');
88	  var gameSel = document.getElementById('game');
89	  var capSel = document.getElementById('capacity');
90	  var capHint = document.getElementById('capacity-hint');
91	  var submitBtn = document.getElementById('submit');
92	  var formMsg = document.getElementById('form-msg');
93	  var listArea = document.getElementById('list-area');
94	  var emptyTip = document.getElementById('empty-tip');
95	
96	  var GAME_LABELS = { gomoku: '五子棋', ludo: '飞行棋' };
97	  var STATUS_LABELS = { waiting: '未开始' };
98	
99	  // 按所选规则重建人数上限选项。
100	  function syncCapacity() {
101	    var game = gameSel.value;
102	    var prev = capSel.value;
103	    capSel.innerHTML = '';
104	    if (game === 'gomoku') {
105	      capSel.disabled = false;
106	      addOption('', '固定 2 人');
107	      addOption('2', '2 人');
108	      capSel.value = '2';
109	      capHint.textContent = '五子棋人数上限固定为 2 人。';
110	    } else if (game === 'ludo') {
111	      capSel.disabled = false;
112	      addOption('', '请选择人数上限…');
113	      [2, 3, 4].forEach(function (n) { addOption(String(n), n + ' 人'); });
114	      capSel.value = (prev === '2' || prev === '3' || prev === '4') ? prev : '';
115	      capHint.textContent = '飞行棋人数上限允许 2 至 4 人。';
116	    } else {
117	      capSel.disabled = true;
118	      addOption('', '请先选择游戏规则');
119	      capHint.textContent = '五子棋人数固定为 2 人；飞行棋允许 2 至 4 人。';
120	    }
121	  }
122	
123	  function addOption(value, text) {
124	    var opt = document.createElement('option');
125	    opt.value = value;
126	    opt.textContent = text;
127	    capSel.appendChild(opt);
128	  }
129	
130	  gameSel.addEventListener('change', syncCapacity);
131	
132	  function showMessage(kind, text) {
133	    formMsg.className = 'msg show ' + kind;
134	    formMsg.textContent = text;
135	  }
136	  function clearMessage() {
137	    formMsg.className = 'msg';
138	    formMsg.textContent = '';
139	  }
140	
141	  // 与服务端一致的提交前校验；服务端仍会再次校验。
142	  function validate(payload) {
143	    var nameLen = Array.from(payload.name.trim()).length;
144	    if (nameLen === 0) return '请填写房间名称。';
145	    if (nameLen > 40) return '房间名称去掉首尾空白后不能超过 40 个字符。';
146	    if (payload.game !== 'gomoku' && payload.game !== 'ludo') return '请选择游戏规则。';
147	    if (payload.game === 'gomoku' && payload.capacity !== 2) return '五子棋的人数上限固定为 2 人。';
148	    if (payload.game === 'ludo' && !(payload.capacity >= 2 && payload.capacity <= 4)) {
149	      return '飞行棋的人数上限必须为 2 至 4 人。';
150	    }
151	    var t = payload.turnSeconds;
152	    if (t !== 0 && !(Number.isInteger(t) && t >= 10 && t <= 600)) {
153	      return '每步时间限制只能填 0（不限时）或 10 至 600 之间的整数秒。';
154	    }
155	    return null;
156	  }
157	
158	  form.addEventListener('submit', function (event) {
159	    event.preventDefault();
160	    clearMessage();
161	
162	    var nameInput = document.getElementById('name');
163	    var turnInput = document.getElementById('turnSeconds');
164	    var turnRaw = turnInput.value.trim();
165	    var payload = {
166	      name: nameInput.value,
167	      game: gameSel.value,
168	      capacity: capSel.value === '' ? null : parseInt(capSel.value, 10),
169	      turnSeconds: turnRaw === '' ? null : Number(turnRaw)
170	    };
171	
172	    // 漏填要明确报错，绝不补默认值。
173	    if (payload.name.trim() === '') return showMessage('error', '请填写房间名称。'), false;
174	    if (!payload.game) return showMessage('error', '请选择游戏规则。'), false;
175	    if (payload.capacity === null) return showMessage('error', '请选择人数上限。'), false;
176	    if (turnRaw === '') return showMessage('error', '请填写每步时间限制（0 表示不限时）。'), false;
177	    if (!/^-?\d+$/.test(turnRaw)) return showMessage('error', '时间限制必须是整数秒，不能含小数。'), false;
178	
179	    var problem = validate({
180	      name: payload.name,
181	      game: payload.game,
182	      capacity: payload.capacity,
183	      turnSeconds: Number(turnRaw)
184	    });
185	    if (problem) { showMessage('error', problem); return; }
186	
187	    payload.turnSeconds = Number(turnRaw);
188	    submit(payload);
189	  });
190	
191	  function submit(payload) {
192	    submitBtn.disabled = true;
193	    fetch('/api/rooms', {
194	      method: 'POST',
195	      headers: { 'Content-Type': 'application/json' },
196	      body: JSON.stringify(payload)
197	    }).then(function (resp) {
198	      return resp.json().catch(function () { return {}; }).then(function (data) {
199	        return { ok: resp.ok, status: resp.status, data: data };
200	      });
201	    }).then(function (result) {
202	      if (result.ok && result.status === 201) {
203	        showMessage('ok', '房间已创建，编号：' + result.data.id);
204	        form.reset();
205	        syncCapacity();
206	        return loadRooms();
207	      }
208	      // 创建失败：保留填写内容，仅显示原因。
209	      var reason = result.data && result.data.error ? result.data.error
210	                 : ('创建失败（HTTP ' + result.status + '）');
211	      showMessage('error', reason);
212	    }).catch(function () {
213	      showMessage('error', '无法连接服务，请确认服务仍在运行后重试。');
214	    }).finally(function () {
215	      submitBtn.disabled = false;
216	    });
217	  }
218	
219	  function formatTime(iso) {
220	    var d = new Date(iso);
221	    if (isNaN(d.getTime())) return iso;
222	    var pad = function (n) { return String(n).padStart(2, '0'); };
223	    var text = d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()) +
224	      ' ' + pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds());
225	    return { text: text, title: iso };
226	  }
227	
228	  function renderRooms(rooms) {
229	    listArea.innerHTML = '';
230	    if (!rooms.length) {
231	      var p = document.createElement('p');
232	      p.className = 'empty';
233	      p.textContent = '还没有房间记录。';
234	      listArea.appendChild(p);
235	      return;
236	    }
237	    var table = document.createElement('table');
238	    table.innerHTML =
239	      '<thead><tr>' +
240	      '<th>房间编号</th><th>名称</th><th>规则</th><th>人数上限</th>' +
241	      '<th>时间限制</th><th>状态</th><th>创建时间</th>' +
242	      '</tr></thead>';
243	    var tbody = document.createElement('tbody');
244	    rooms.forEach(function (r) {
245	      var tr = document.createElement('tr');
246	
247	      var tdId = document.createElement('td');
248	      tdId.className = 'id';
249	      tdId.textContent = r.id || '';
250	      tr.appendChild(tdId);
251	
252	      var tdName = document.createElement('td');
253	      tdName.textContent = r.name || '';
254	      tr.appendChild(tdName);
255	
256	      var tdGame = document.createElement('td');
257	      tdGame.textContent = GAME_LABELS[r.game] || r.game || '';
258	      tr.appendChild(tdGame);
259	
260	      var tdCap = document.createElement('td');
261	      tdCap.textContent = (r.capacity != null ? r.capacity : '') + ' 人';
262	      tr.appendChild(tdCap);
263	
264	      var tdTurn = document.createElement('td');
265	      if (r.turnSeconds === 0) tdTurn.textContent = '不限时';
266	      else tdTurn.textContent = r.turnSeconds + ' 秒';
267	      tr.appendChild(tdTurn);
268	
269	      var tdStatus = document.createElement('td');
270	      var badge = document.createElement('span');
271	      badge.className = 'badge';
272	      badge.textContent = STATUS_LABELS[r.status] || r.status || '';
273	      tdStatus.appendChild(badge);
274	      tr.appendChild(tdStatus);
275	
276	      var tdTime = document.createElement('td');
277	      var t = formatTime(r.createdAt || '');
278	      tdTime.textContent = t.text;
279	      tdTime.title = t.title;
280	      tr.appendChild(tdTime);
281	
282	      tbody.appendChild(tr);
283	    });
284	    table.appendChild(tbody);
285	    listArea.appendChild(table);
286	  }
287	
288	  function loadRooms() {
289	    return fetch('/api/rooms', { headers: { 'Accept': 'application/json' } })
290	      .then(function (resp) {
291	        if (!resp.ok) throw new Error('HTTP ' + resp.status);
292	        return resp.json();
293	      })
294	      .then(function (data) {
295	        var rooms = Array.isArray(data && data.rooms) ? data.rooms : [];
296	        renderRooms(rooms);
297	      })
298	      .catch(function () {
299	        listArea.innerHTML = '';
300	        var p = document.createElement('p');
301	        p.className = 'list-error';
302	        p.textContent = '房间列表加载失败，请稍后刷新重试。已有数据不会因此丢失。';
303	        listArea.appendChild(p);
304	      });
305	  }
306	
307	  syncCapacity();
308	  loadRooms();
309	})();
310	</script>
311	</html>
