// startServer 在 dataDir 上启动服务子进程，返回基地址（如 http://127.0.0.1:12345）。
func startServer(t *testing.T, dataDir string) string {
	t.Helper()
	cmd := exec.Command(serverBin, "serve", "--host", "127.0.0.1", "--port", "0", "--data-dir", dataDir)
