			if line := scanner.Text(); strings.Contains(line, "listening on") {
				lineCh <- line
				return
			}
		}
		lineCh <- ""
	}()

	select {
	case line := <-lineCh:
		if line == "" {
			t.Fatal("服务在输出监听地址前退出")
		}
		idx := strings.Index(line, "http://")
		if idx < 0 {
			t.Fatalf("无法从服务输出解析地址: %q", line)
