// getRooms 查询房间列表，返回状态码与记录数组（保持服务端顺序）。
func getRooms(t *testing.T, baseURL string) (int, []any) {
	t.Helper()
	resp, err := httpClient.Get(baseURL + "/api/rooms")
	if err != nil {
		t.Fatalf("GET /api/rooms 失败: %v", err)
