		t.Fatalf("创建状态码 = %d，期望 201，响应: %v", status, created)
	}
	if got, want := created["name"], "周末  棋社"; got != want {
		t.Fatalf("名称 = %q，期望 %q（内部空格保留）", got, want)
	}

	// U+FEFF 不属于首尾空白，应保留并计入长度。
	status, created = postRoom(t, baseURL, `{"name":"\ufeff棋社\ufeff","game":"gomoku","capacity":2,"turnSeconds":0}`)
	if status != http.StatusCreated {
		t.Fatalf("创建状态码 = %d，期望 201，响应: %v", status, created)
	}
	if got, want := created["name"], "\ufeff棋社\ufeff"; got != want {
		t.Fatalf("名称 = %q，期望 %q（U+FEFF 保留）", got, want)
	}

	// 恰好 40 个码点（含一个补充平面表情，按 1 个码点计）可以创建。
	name40 := strings.Repeat("棋", 39) + "😀"
	body, _ := json.Marshal(map[string]any{"name": name40, "game": "gomoku", "capacity": 2, "turnSeconds": 0})
	status, created = postRoom(t, baseURL, string(body))
	if status != http.StatusCreated {
		t.Fatalf("40 码点名称状态码 = %d，期望 201，响应: %v", status, created)
	}
	if got := created["name"]; got != name40 {
		t.Fatalf("名称 = %q，期望 %q", got, name40)
	}

	// 41 个码点必须拒绝：400、说明原因、不返回编号、已有数据不变。
	name41 := strings.Repeat("棋", 41)
	body, _ = json.Marshal(map[string]any{"name": name41, "game": "gomoku", "capacity": 2, "turnSeconds": 0})
	status, resp := postRoom(t, baseURL, string(body))
	if status != http.StatusBadRequest {
		t.Fatalf("41 码点名称状态码 = %d，期望 400，响应: %v", status, resp)
	}
	errMsg, _ := resp["error"].(string)
	if !strings.Contains(errMsg, "40") {
		t.Fatalf("error 应说明超过 40 个字符，实际: %q", errMsg)
	}
	if _, ok := resp["id"]; ok {
		t.Fatalf("被拒绝的请求不应返回房间，实际: %v", resp)
	}

	// 只含应被去掉的空白时按空名称拒绝。
	status, resp = postRoom(t, baseURL, `{"name":"   \t","game":"gomoku","capacity":2,"turnSeconds":0}`)
	if status != http.StatusBadRequest {
		t.Fatalf("纯空白名称状态码 = %d，期望 400，响应: %v", status, resp)
	}
	errMsg, _ = resp["error"].(string)
	if !strings.Contains(errMsg, "空") {
		t.Fatalf("error 应说明名称不能为空，实际: %q", errMsg)
	}

	// 三次成功创建追加在原记录之后；两次拒绝不产生任何记录。
	_, rooms := getRooms(t, baseURL)
	if len(rooms) != 5 {
		t.Fatalf("房间数量 = %d，期望 5（原有 2 条 + 新增 3 条）", len(rooms))
	}
	seedRecords := decodeRecords(t, seed)
	if !reflect.DeepEqual(rooms[:2], seedRecords) {
		t.Fatalf("原有房间被改写或重新排序：\n得到: %v\n期望: %v", rooms[:2], seedRecords)
	}
}
```

